90	function useActiveHref(groups: NavGroup[], pathname: string): string | null {
91	  const allHrefs = groups.flatMap((g) => g.items.map((i) => i.href));
92	  const matches = allHrefs.filter((h) => pathname === h || pathname.startsWith(`${h}/`));
93	  if (matches.length === 0) return null;
94	  return matches.sort((a, b) => b.length - a.length)[0];
95	}
