7	export type AddIngredientState = { error: string | null };
8	
9	export async function addIngredient(
10	  businessId: string,
11	  _prevState: AddIngredientState,
12	  formData: FormData,
13	): Promise<AddIngredientState> {
14	  const name = (formData.get("name") as string)?.trim();
15	  const unit = (formData.get("unit") as string)?.trim();
16	  const unitCostRaw = formData.get("unitCost") as string;
17	  const stockRaw = formData.get("stock") as string;
18	  const minStockRaw = formData.get("minStock") as string;
19	
20	  if (!name) {
21	    return { error: "Nama bahan wajib diisi." };
22	  }
23	  if (!unit) {
24	    return { error: "Satuan wajib diisi (mis. gr, ml, pcs)." };
25	  }
26	
27	  const unitCost = unitCostRaw ? Number(unitCostRaw) : 0;
28	  if (Number.isNaN(unitCost) || unitCost < 0) {
29	    return { error: "Harga per satuan harus angka dan tidak boleh negatif." };
30	  }
31	
32	  const stock = stockRaw ? Number(stockRaw) : 0;
33	  if (Number.isNaN(stock) || stock < 0) {
34	    return { error: "Stok harus angka dan tidak boleh negatif." };
35	  }
36	
37	  const minStock = minStockRaw ? Number(minStockRaw) : 0;
38	  if (Number.isNaN(minStock) || minStock < 0) {
39	    return { error: "Stok minimum harus angka dan tidak boleh negatif." };
40	  }
41	
42	  const supabase = await createClient();
43	  const { error } = await supabase.from("ingredients").insert({
44	    business_id: businessId,
45	    name,
46	    unit,
47	    unit_cost: unitCost,
48	    stock,
49	    min_stock: minStock,
50	  });
51	
52	  if (error) {
53	    return { error: error.message };
54	  }
55	
56	  await logActivity(
57	    supabase,
58	    businessId,
59	    "produk",
60	    "sukses",
61	    `Bahan baku baru: ${name}`,
62	    `Stok ${stock} ${unit}`,
63	  );
64	  revalidatePath(`/business/${businessId}/ingredients`);
65	  return { error: null };
66	}
