70	export async function editIngredient(
71	  businessId: string,
72	  ingredientId: string,
73	  _prevState: EditIngredientState,
74	  formData: FormData,
75	): Promise<EditIngredientState> {
76	  const name = (formData.get("name") as string)?.trim();
77	  const unit = (formData.get("unit") as string)?.trim();
78	  const unitCostRaw = formData.get("unitCost") as string;
79	  const minStockRaw = formData.get("minStock") as string;
80	
81	  if (!name) {
82	    return { error: "Nama bahan wajib diisi." };
83	  }
84	  if (!unit) {
85	    return { error: "Satuan wajib diisi (mis. gr, ml, pcs)." };
86	  }
87	
88	  const unitCost = unitCostRaw ? Number(unitCostRaw) : 0;
89	  if (Number.isNaN(unitCost) || unitCost < 0) {
90	    return { error: "Harga per satuan harus angka dan tidak boleh negatif." };
91	  }
92	
93	  const minStock = minStockRaw ? Number(minStockRaw) : 0;
94	  if (Number.isNaN(minStock) || minStock < 0) {
95	    return { error: "Stok minimum harus angka dan tidak boleh negatif." };
96	  }
97	
98	  const supabase = await createClient();
99	  const { error } = await supabase
100	    .from("ingredients")
101	    .update({ name, unit, unit_cost: unitCost, min_stock: minStock })
102	    .eq("id", ingredientId)
103	    .eq("business_id", businessId);
104	
105	  if (error) {
106	    return { error: error.message };
107	  }
108	
109	  await logActivity(supabase, businessId, "produk", "info", `Bahan baku diubah: ${name}`);
110	  revalidatePath(`/business/${businessId}/ingredients`);
111	  return { error: null };
112	}
