114	export type AdjustStockResult = { error: string | null };
115	
116	export async function adjustIngredientStock(
117	  businessId: string,
118	  ingredientId: string,
119	  newStock: number,
120	  reason: string,
121	): Promise<AdjustStockResult> {
122	  if (Number.isNaN(newStock) || newStock < 0) {
123	    return { error: "Stok fisik harus angka dan tidak boleh negatif." };
124	  }
125	  reason = reason.trim();
126	  if (!reason) {
127	    return { error: "Alasan penyesuaian wajib diisi." };
128	  }
129	
130	  const supabase = await createClient();
131	
132	  const { data: ingredient } = await supabase
133	    .from("ingredients")
134	    .select("id, name, unit, stock")
135	    .eq("id", ingredientId)
136	    .eq("business_id", businessId)
137	    .single();
138	
139	  if (!ingredient) {
140	    return { error: "Bahan baku tidak ditemukan." };
141	  }
142	
143	  const stockBefore = Number(ingredient.stock);
144	  const diff = newStock - stockBefore;
145	
146	  if (diff === 0) {
147	    return { error: "Stok fisik sama dengan stok sistem, tidak ada yang disesuaikan." };
148	  }
149	
150	  const { error: updateError } = await supabase
151	    .from("ingredients")
152	    .update({ stock: newStock })
153	    .eq("id", ingredientId);
154	
155	  if (updateError) {
156	    return { error: updateError.message };
157	  }
158	
159	  await supabase.from("stock_adjustments").insert({
160	    business_id: businessId,
161	    ingredient_id: ingredientId,
162	    item_name: ingredient.name,
163	    unit: ingredient.unit,
164	    stock_before: stockBefore,
165	    stock_after: newStock,
166	    diff,
167	    reason,
168	  });
169	
170	  await logActivity(
171	    supabase,
172	    businessId,
173	    "produk",
174	    "warning",
175	    `Penyesuaian stok: ${ingredient.name}`,
176	    `${stockBefore} → ${newStock} ${ingredient.unit} (${diff > 0 ? "+" : ""}${diff}) · ${reason}`,
177	  );
178	  revalidatePath(`/business/${businessId}/ingredients`);
179	  return { error: null };
180	}
