182	export async function deleteIngredient(businessId: string, ingredientId: string) {
183	  const supabase = await createClient();
184	
185	  const { data: ingredient } = await supabase
186	    .from("ingredients")
187	    .select("name")
188	    .eq("id", ingredientId)
189	    .eq("business_id", businessId)
190	    .maybeSingle();
191	
192	  await supabase
193	    .from("ingredients")
194	    .update({ deleted_at: new Date().toISOString() })
195	    .eq("id", ingredientId)
196	    .eq("business_id", businessId);
197	
198	  if (ingredient) {
199	    await logActivity(
200	      supabase,
201	      businessId,
202	      "produk",
203	      "warning",
204	      `Bahan baku dihapus: ${ingredient.name}`,
205	    );
206	  }
207	  revalidatePath(`/business/${businessId}/ingredients`);
208	}
